// Package migrations embeds Promptdam's Postgres migrations (the product
// graph, generated by Atlas from server/ent/schema) and its ClickHouse
// migrations (the request log and its rollups).
package migrations

import (
	"embed"
	"io/fs"

	"github.com/hasan-muzak/keel-core/pkg/db"
	"github.com/hasan-muzak/keel-core/pkg/events"
)

//go:embed postgres/*.sql
var postgresFS embed.FS

// Postgres is Promptdam's product-graph migration set, applied after the
// core.
func Postgres() db.MigrationSet {
	sub, err := fs.Sub(postgresFS, "postgres")
	if err != nil {
		panic(err) // the embedded directory always exists
	}
	return db.MigrationSet{Name: "promptdam", FS: sub, Table: "goose_promptdam_version"}
}

//go:embed clickhouse/*.sql
var clickhouseFS embed.FS

// ClickHouse is Promptdam's ClickHouse migration set.
func ClickHouse() events.MigrationSet {
	sub, err := fs.Sub(clickhouseFS, "clickhouse")
	if err != nil {
		panic(err) // the embedded directory always exists
	}
	return events.MigrationSet{Name: "promptdam", FS: sub, Table: "goose_promptdam_version"}
}
